package com.zerohitsplats;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ZeroHitsplatsOverlayTest
{
    @Test public void idleOverlayHasDraggableBoundsAndPreservesSavedPosition()
    {
        Client client = mock(Client.class);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getViewportWidth()).thenReturn(800);
        ZeroHitsplatsOverlay overlay = new ZeroHitsplatsOverlay(client, new ZeroHitsplatsConfig() {});
        Graphics2D g = new BufferedImage(800, 600, BufferedImage.TYPE_INT_ARGB).createGraphics();
        try
        {
            Dimension bounds = overlay.render(g);
            assertTrue(overlay.isMovable());
            assertTrue(bounds.width > 0 && bounds.height > 120);
            overlay.setPreferredLocation(new Point(250, 200));
            overlay.getBounds().setLocation(250, 200);
            overlay.render(g);
            assertEquals(new Point(250, 200), overlay.getBounds().getLocation());
        }
        finally { g.dispose(); }
    }

    @Test public void iconScalesIndependentlyOfFont()
    {
        BufferedImage icon = new BufferedImage(12, 12, BufferedImage.TYPE_INT_ARGB);
        Graphics2D source = icon.createGraphics();
        source.setColor(Color.BLUE); source.fillRect(0, 0, 12, 12); source.dispose();
        assertEquals(16 * 16, bluePixels(icon, 16));
        assertEquals(48 * 48, bluePixels(icon, 48));
    }

    @Test public void snapAnchorPositionIsNotOverwrittenByDefaultOffsets()
    {
        Client client = mock(Client.class);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getViewportWidth()).thenReturn(800);
        ZeroHitsplatsOverlay overlay = new ZeroHitsplatsOverlay(client, new ZeroHitsplatsConfig() {});
        overlay.setPreferredPosition(OverlayPosition.TOP_RIGHT);
        overlay.getBounds().setLocation(700, 25); // Position supplied by RuneLite's anchor layout.
        Graphics2D g = new BufferedImage(800, 600, BufferedImage.TYPE_INT_ARGB).createGraphics();
        try
        {
            overlay.render(g);
            assertTrue(overlay.isSnappable());
            assertEquals(new Point(700, 25), overlay.getBounds().getLocation());
            overlay.getBounds().setLocation(600, 25); // Anchor moved after viewport resize.
            overlay.render(g);
            assertEquals(new Point(600, 25), overlay.getBounds().getLocation());
            overlay.setPreferredPosition(null); // Alt-right-click resets placement.
            overlay.render(g);
            assertNotEquals(new Point(600, 25), overlay.getBounds().getLocation());
        }
        finally { g.dispose(); }
    }

    private int bluePixels(BufferedImage icon, int size)
    {
        BufferedImage image = new BufferedImage(200, 100, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setFont(new Font("Dialog", Font.PLAIN, 16));
        ZeroHitsplatsOverlay.drawDrop(g, icon, 100, 50, size);
        assertEquals(16, g.getFont().getSize());
        g.dispose();
        int count = 0;
        for (int x = 0; x < image.getWidth(); x++)
        {
            for (int y = 0; y < image.getHeight(); y++)
            {
                if (image.getRGB(x, y) == Color.BLUE.getRGB()) { count++; }
            }
        }
        return count;
    }
}

package com.zerohitsplats;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.Skill;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.FakeXpDrop;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Zero Hitsplats",
    description = "Shows a scrolling blue hitsplat and zero when a melee or ranged attack gives no combat XP",
    tags = {"combat", "xp", "zero", "miss", "hitsplat"}
)
public class ZeroHitsplatsPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ZeroHitsplatsConfig config;
    @Inject private ZeroHitsplatsOverlay overlay;
    @Inject private OverlayManager overlayManager;
    @Inject private SpriteManager spriteManager;
    private final AttackBatch attacks = new AttackBatch();
    private final int[] xp = new int[Skill.values().length];
    // Two identity sets swapped each tick instead of allocating a fresh one: `seen` holds last
    // tick's projectiles, `seenSpare` is refilled as this tick's and the two trade places.
    private Set<Projectile> seen = Collections.newSetFromMap(new IdentityHashMap<>());
    private Set<Projectile> seenSpare = Collections.newSetFromMap(new IdentityHashMap<>());
    private boolean initialized;
    private long lastPreview;

    @Provides
    ZeroHitsplatsConfig provideConfig(ConfigManager manager) { return manager.getConfig(ZeroHitsplatsConfig.class); }

    @Override
    protected void startUp()
    {
        reset();
        overlayManager.add(overlay);
        // Baseline on the next game tick, avoiding startup XP being mistaken for a hit.
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        reset();
    }

    private void reset()
    {
        initialized = false;
        attacks.clear();
        seen.clear();
        seenSpare.clear();
        overlay.clear();
        lastPreview = 0;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN) { reset(); }
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event)
    {
        Player player = client.getLocalPlayer();
        if (!initialized || player == null || event.getActor() != player) { return; }
        if (AttackAnimations.contains(player.getAnimation()) && !CombatStyle.isMagic(client))
        {
            attacks.animation();
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        int index = event.getSkill().ordinal();
        int delta = event.getXp() - xp[index];
        xp[index] = event.getXp();
        if (initialized && delta > 0) { recordXp(event.getSkill()); }
    }

    @Subscribe
    public void onFakeXpDrop(FakeXpDrop event)
    {
        if (initialized && event.getXp() > 0) { recordXp(event.getSkill()); }
    }

    private void recordXp(Skill skill)
    {
        // Any combat XP suppresses a zero, including base XP from magic casts.
        if (skill == Skill.HITPOINTS || skill == Skill.ATTACK || skill == Skill.STRENGTH
            || skill == Skill.DEFENCE || skill == Skill.RANGED || skill == Skill.MAGIC)
        {
            attacks.damageXp();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) { return; }
        overlay.setSprite(spriteManager.getSprite(SpriteID.Hitmark.HITSPLAT_BLUE_MISS, 0));
        final Player localPlayer = client.getLocalPlayer();
        final Set<Projectile> active = seenSpare;
        active.clear();
        // Neither the animation check nor isMagic() depends on the projectile, and nothing in the
        // loop body mutates game state, so both are loop-invariant. isMagic() is not cheap — two
        // varbit reads, two enum lookups, a struct fetch — and the original short-circuit meant it
        // was never evaluated on ticks with no qualifying projectile, so resolve it lazily to keep
        // idle ticks free.
        Boolean meleeOrRangedAttack = null;
        for (Projectile p : client.getProjectiles())
        {
            active.add(p);
            if (initialized && !seen.contains(p) && p.getSourceActor() == localPlayer
                && p.getTargetActor() != null)
            {
                if (meleeOrRangedAttack == null)
                {
                    meleeOrRangedAttack = AttackAnimations.contains(localPlayer.getAnimation())
                        && !CombatStyle.isMagic(client);
                }
                if (meleeOrRangedAttack)
                {
                    attacks.projectile();
                }
            }
        }
        // retainAll(active) then addAll(active) left `seen` holding exactly `active`, so swap.
        seenSpare = seen;
        seen = active;
        if (!initialized)
        {
            for (Skill skill : Skill.values()) { xp[skill.ordinal()] = client.getSkillExperience(skill); }
            attacks.clear();
            initialized = true;
            return;
        }
        if (attacks.finish())
        {
            overlay.addDrop();
        }
        long now = System.nanoTime();
        if (config.preview() && now - lastPreview > 2_000_000_000L)
        {
            overlay.addDrop();
            lastPreview = now;
        }
    }

}

package com.zerohitsplats;

/** Reconciles events at the packet-batch boundary, regardless of XP/animation order. */
final class AttackBatch
{
    private boolean animation;
    private boolean projectile;
    private boolean damageXp;
    private int batch;
    private int lastAnimation = -100;
    private int lastProjectile = -100;
    private int lastDamageXp = -100;

    void animation() { animation = true; }
    void projectile() { projectile = true; }
    void damageXp() { damageXp = true; }

    boolean finish()
    {
        // A projectile may first appear one packet batch after its launch animation.
        // Conversely, an animation notification can follow the projectile evidence.
        boolean attack = (animation && batch - lastProjectile > 1)
            || (projectile && batch - lastAnimation > 1);
        boolean zero = attack && !damageXp
            && !(projectile && !animation && batch - lastDamageXp <= 1);
        if (animation) { lastAnimation = batch; }
        if (projectile) { lastProjectile = batch; }
        if (damageXp) { lastDamageXp = batch; }
        animation = projectile = damageXp = false;
        batch++;
        return zero;
    }

    void clear()
    {
        animation = projectile = damageXp = false;
        batch = 0;
        lastAnimation = lastProjectile = lastDamageXp = -100;
    }
}

